# Claude Cowork (Amazon Bedrock) - machine-wide uninstaller for Windows.
#
# GENERATED by scripts/install/build-windows-cowork.sh for release 2026-07-16-160359. Do not edit by hand.
# Deploy as an Intune platform script with the same settings as install-cowork.ps1
# (SYSTEM, 64-bit PowerShell host).
#
# Removes only what install-cowork.ps1 recorded in HKLM\SOFTWARE\ccwb: the policy values it wrote
# under HKLM\SOFTWARE\Policies\Claude (restoring any value it had overwritten; the key itself is
# removed only if it is then empty), the marker, and C:\ProgramData\ccwb. Without the marker it
# changes nothing. Per-user credential caches in user profiles are left alone.
#
# Test override (never set in production): CCWB_INSTALL_ROOT, CCWB_POLICY_KEY, CCWB_MARKER_KEY, CCWB_LOG.
#Requires -Version 5.1
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

function Get-Setting([string]$Name, [string]$Default) {
    $v = [Environment]::GetEnvironmentVariable($Name)
    if ([string]::IsNullOrEmpty($v)) { return $Default }
    return $v
}
$ImeLogs = 'C:\ProgramData\Microsoft\IntuneManagementExtension\Logs'
if (Test-Path -LiteralPath $ImeLogs -PathType Container) { $DefaultLog = "$ImeLogs\ccwb-cowork.log" }
else { $DefaultLog = "$env:windir\Logs\ccwb-cowork.log" }
$InstallRoot = Get-Setting 'CCWB_INSTALL_ROOT' 'C:\ProgramData\ccwb'
$PolicyKey   = Get-Setting 'CCWB_POLICY_KEY'   'HKLM:\SOFTWARE\Policies\Claude'
$MarkerKey   = Get-Setting 'CCWB_MARKER_KEY'   'HKLM:\SOFTWARE\ccwb'
$LogFile     = Get-Setting 'CCWB_LOG'          $DefaultLog

function Write-Log([string]$Message) {
    $line = '{0} ccwb-cowork-uninstall: {1}' -f (Get-Date -Format 's'), $Message
    Write-Output $line
    try { Add-Content -LiteralPath $LogFile -Value $line } catch { }
}
function Stop-Uninstall([string]$Message) { Write-Log "ERROR: $Message"; exit 1 }
function Get-RegValue([string]$Key, [string]$Name) {
    if (-not (Test-Path -LiteralPath $Key)) { return $null }
    return (Get-Item -LiteralPath $Key).GetValue($Name, $null, 'DoNotExpandEnvironmentNames')
}

if (-not [Environment]::Is64BitProcess) {
    Stop-Uninstall 'running in 32-bit PowerShell: enable "Run script in 64 bit PowerShell Host" in Intune'
}
$principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
    Stop-Uninstall 'must run as SYSTEM or an administrator'
}
if (-not (Test-Path -LiteralPath $MarkerKey)) {
    Write-Log "no install record at $MarkerKey; nothing to remove"
    exit 0
}

# --- Policy: remove our values, restore what we overwrote -----------------------------------
# PS 5.1 ConvertFrom-Json emits an array as ONE object: enumerate it, never wrap it in @(...).
$names = New-Object System.Collections.Generic.List[string]
$recordedNames = Get-RegValue $MarkerKey 'PolicyNames'
if ($recordedNames) { foreach ($x in ($recordedNames | ConvertFrom-Json)) { $names.Add([string]$x) } }
$prior = @{}
$recordedPrior = Get-RegValue $MarkerKey 'PriorValues'
if ($recordedPrior) { foreach ($p in ($recordedPrior | ConvertFrom-Json).PSObject.Properties) { $prior[$p.Name] = [string]$p.Value } }

if (Test-Path -LiteralPath $PolicyKey) {
    foreach ($n in $names) {
        if ($prior.ContainsKey($n)) {
            New-ItemProperty -LiteralPath $PolicyKey -Name $n -Value ([string]$prior[$n]) -PropertyType String -Force | Out-Null
        } else {
            Remove-ItemProperty -LiteralPath $PolicyKey -Name $n -ErrorAction SilentlyContinue
        }
    }
    $key = Get-Item -LiteralPath $PolicyKey
    if ($key.ValueCount -eq 0 -and $key.SubKeyCount -eq 0) { Remove-Item -LiteralPath $PolicyKey -Force }
}

# --- Files: rename aside (fails cleanly while in use), then delete --------------------------
if (Test-Path -LiteralPath $InstallRoot) {
    $aside = Join-Path (Split-Path -Parent $InstallRoot) ((Split-Path -Leaf $InstallRoot) + '.old-' + [IO.Path]::GetRandomFileName())
    try { [IO.Directory]::Move($InstallRoot, $aside) }
    catch { Stop-Uninstall "install is in use (Claude Desktop running?); quit Claude and retry: $($_.Exception.Message)" }
    $eap = $ErrorActionPreference; $ErrorActionPreference = 'Continue'
    # rd /s removes junctions/symlinks themselves and never follows them.
    try { & cmd.exe /d /c rd /s /q "`"$aside`"" 2>&1 | Out-Null } finally { $ErrorActionPreference = $eap }
    if (Test-Path -LiteralPath $aside) { Write-Log "files left at $aside (in use); delete after reboot" }
}

Remove-Item -LiteralPath $MarkerKey -Recurse -Force
Write-Log "removed $($names.Count) policy values ($($prior.Count) restored), marker and $InstallRoot"
exit 0
